From 87b6f815ce86778c6b129cb0fbe171d6f60aba67 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:10:58 +0100
Subject: [PATCH] desktop: keep the old activity visible until the new one
 slides in

The view hides the old containment as soon as the activity changes, so
the screen went black while the new activity loaded and it slid in over
black. Keep the old one shown and start the slide once the new is ready.

BUG: 452104
---
 desktoppackage/contents/views/Desktop.qml | 22 ++++++++++++++++++++--
 1 file changed, 20 insertions(+), 2 deletions(-)

diff --git a/desktoppackage/contents/views/Desktop.qml b/desktoppackage/contents/views/Desktop.qml
index 1be09364ef..ecc7df2a36 100644
--- a/desktoppackage/contents/views/Desktop.qml
+++ b/desktoppackage/contents/views/Desktop.qml
@@ -318,25 +318,43 @@ Item {
             internal.newContainment.visible = false;
             internal.oldContainment.visible = false;
             internal.oldContainment = null;
+        } else if (internal.newContainment && internal.newContainment !== internal.oldContainment) {
+            //A containment was still waiting to be ready for the switch
+            internal.newContainment.visible = false;
         }

         internal.newContainment = containment;
         containment.visible = true;

         if (internal.oldContainment !== null && internal.oldContainment !== containment) {
-            switchAnim.running = true;
+            //The view hides the old containment, but it has to stay visible
+            //until the new one, with its wallpaper loaded, has slid over it
+            internal.oldContainment.visible = true;
+            containment.x = root.width;
+            if (containment.plasmoid.isUiReady) {
+                switchAnim.running = true;
+            }
         } else {
             containment.anchors.left = containmentParent.left;
             containment.anchors.top = containmentParent.top;
             containment.anchors.right = containmentParent.right;
             containment.anchors.bottom = containmentParent.bottom;
-            if (internal.oldContainment) {
+            if (internal.oldContainment && internal.oldContainment !== containment) {
                 internal.oldContainment.visible = false;
             }
             internal.oldContainment = containment;
         }
     }

+    Connections {
+        target: internal.newContainment?.plasmoid ?? null
+        function onUiReadyChanged(uiReady: bool): void {
+            if (uiReady && internal.newContainment !== internal.oldContainment && !switchAnim.running) {
+                switchAnim.running = true;
+            }
+        }
+    }
+
     //some properties that shouldn't be accessible from elsewhere
     QtObject {
         id: internal
-- 
